python3 << 'EOF'
import re

with open('/app/resources/treasury_bulletin_1970_06.txt') as f:
    content = f.read()

# Get the AY-1 data
start = content.find('Monthly series - averages of daily or weekly series')
end = content.find('Weekly series - average for weeks ending')
section = content[start:end]

# Parse each line
lines = section.split('\n')
data_rows = []

for line in lines:
    if '|' in line:
        parts = line.split('|')
        if len(parts) >= 14:
            month = parts[1].strip()
            if month in ['Jan.', 'Feb.', 'Mar.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']:
                yields = []
                for p in parts[2:14]:
                    p = p.strip()
                    p_clean = re.sub(r'\s*\d+/\s*$', '', p).strip()
                    if p_clean == 'nan':
                        yields.append(None)
                    else:
                        try:
                            yields.append(float(p_clean))
                        except:
                            yields.append(None)
                data_rows.append((month, yields))

# Now let's see what the actual yield levels are for each group to identify years
# Looking at Group4 (the last group with highest yields)

print("Group 4 Treasury yields by year block:")
for i in range(3):
    block_data = data_rows[i*12:(i+1)*12]
    treasury_yields = [row[1][9] for row in block_data if row[1][9] is not None]
    corp_yields = [row[1][10] for row in block_data if row[1][10] is not None]
    if treasury_yields:
        print(f"  Year block {i}: Treasury range {min(treasury_yields):.2f}-{max(treasury_yields):.2f}, Corporate range {min(corp_yields):.2f}-{max(corp_yields):.2f}")

# Also check Group 1 for comparison
print("\nGroup 1 Treasury yields by year block:")
for i in range(3):
    block_data = data_rows[i*12:(i+1)*12]
    treasury_yields = [row[1][0] for row in block_data if row[1][0] is not None]
    if treasury_yields:
        print(f"  Year block {i}: Treasury range {min(treasury_yields):.2f}-{max(treasury_yields):.2f}")
EOF
